import{_ as t,a,o,a6 as s}from"./chunks/framework.CJDy2q7X.js";const m=JSON.parse('{"title":"Theme","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"rest","title":"Get Theme","query":"curl -X GET \\"https://your-domain.com/api/shop/theme\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: <storefront-key>\\"\\n","response":"[\\n  {\\n    \\"code\\": \\"default\\",\\n    \\"name\\": \\"Default\\",\\n    \\"sectionTypes\\": [\\n      \\"image_carousel\\",\\n      \\"product_carousel\\",\\n      \\"category_carousel\\",\\n      \\"footer_links\\",\\n      \\"static_content\\",\\n      \\"services_content\\"\\n    ]\\n  }\\n]\\n"}]},"headers":[],"relativePath":"api/rest-api/shop/theme/index.md","filePath":"api/rest-api/shop/theme/index.md","lastUpdated":1789385991000}'),n={name:"api/rest-api/shop/theme/index.md"};function r(i,e,d,c,h,l){return o(),a("div",null,e[0]||(e[0]=[s('<h1 id="theme" tabindex="-1">Theme <a class="header-anchor" href="#theme" aria-label="Permalink to &quot;Theme&quot;">​</a></h1><p>The theme the current channel&#39;s storefront is drawn with, and the section types it can hold.</p><p>Each channel runs exactly one theme, and a section belongs to a theme and a channel together. <a href="/api/rest-api/shop/sections/list.html">List Sections</a> is already scoped to the theme this endpoint reports, so a storefront that only draws sections does not need to read it — it matters when a client picks templates, assets or copy per theme.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/shop/theme</code></td><td>Get the active theme of the current channel</td></tr></tbody></table><h2 id="response-fields" tabindex="-1">Response fields <a class="header-anchor" href="#response-fields" aria-label="Permalink to &quot;Response fields&quot;">​</a></h2><p>Returns a single-entry array, the same shape the other single-resource endpoints use.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>code</code></td><td>string</td><td>Theme code, e.g. <code>default</code>.</td></tr><tr><td><code>name</code></td><td>string</td><td>Display name, falling back to the code when the theme declares none.</td></tr><tr><td><code>sectionTypes</code></td><td>array</td><td>The six section types a theme can hold: <code>image_carousel</code>, <code>product_carousel</code>, <code>category_carousel</code>, <code>footer_links</code>, <code>static_content</code>, <code>services_content</code>.</td></tr></tbody></table><h2 id="use-cases" tabindex="-1">Use cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use cases&quot;">​</a></h2><ul><li><strong>Pick a template set per theme</strong> — read <code>code</code> once at boot and choose the component map a storefront renders sections with.</li><li><strong>Validate a section type before rendering</strong> — <code>sectionTypes</code> is the closed set <code>/api/shop/sections</code> can return, so a client can fall back gracefully on anything outside it.</li></ul><h2 id="best-practices" tabindex="-1">Best practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best practices&quot;">​</a></h2><ul><li><strong>A channel that has never been pointed at a theme reports the shop default</strong>, so <code>code</code> is never null and needs no fallback client-side.</li><li><strong>This is the storefront view of a theme, not the admin gallery.</strong> Author, version, screenshot and install state belong to the admin <a href="/api/rest-api/admin/appearance/themes/list.html">theme gallery</a> and are deliberately not public.</li><li><strong><code>sectionTypes</code> is the catalogue of types, not what this channel holds.</strong> For the sections a channel actually draws, read <a href="/api/rest-api/shop/sections/list.html">List Sections</a>.</li></ul><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>Public. Requires only the storefront key.</p>',14)]))}const u=t(n,[["render",r]]);export{m as __pageData,u as default};
